/**
 * Finds the longest common subsequence of `side` against `base`, comparing
 * lines as exact strings. When several subsequences share the maximum
 * length, picks the one whose matches occur earliest by walking both
 * documents from the start: a match is taken whenever the current lines are
 * equal, and otherwise the side whose remaining subsequence (after
 * advancing) is strictly the longer one is advanced, with ties advancing
 * the base.
 *
 * Returns the matches as `[sideIndex, baseIndex]` pairs, increasing in both
 * coordinates.
 */
function computeMatches(side, base) {
  const n = side.length
  const m = base.length
  const dp = new Array(n + 1)
  for (let i = 0; i <= n; i++) dp[i] = new Uint32Array(m + 1)
  for (let i = n - 1; i >= 0; i--) {
    const row = dp[i]
    const nextRow = dp[i + 1]
    for (let j = m - 1; j >= 0; j--) {
      row[j] = side[i] === base[j] ? nextRow[j + 1] + 1 : Math.max(nextRow[j], row[j + 1])
    }
  }
  const matches = []
  let i = 0
  let j = 0
  while (i < n && j < m) {
    if (side[i] === base[j]) {
      matches.push([i, j])
      i++
      j++
    } else if (dp[i + 1][j] > dp[i][j + 1]) {
      i++
    } else {
      j++
    }
  }
  return matches
}

/**
 * Turns the matches between `side` and `base` into the runs the LCS does
 * not cover: each a run of base lines replaced by a run of side lines,
 * tagged with which side made it.
 */
function computeChanges(side, base, sideName) {
  const matches = computeMatches(side, base)
  const changes = []
  let prevSide = 0
  let prevBase = 0
  for (const [si, bi] of matches) {
    if (si > prevSide || bi > prevBase) {
      changes.push({ side: sideName, baseStart: prevBase, baseEnd: bi, sideStart: prevSide, sideEnd: si })
    }
    prevSide = si + 1
    prevBase = bi + 1
  }
  if (prevSide < side.length || prevBase < base.length) {
    changes.push({ side: sideName, baseStart: prevBase, baseEnd: base.length, sideStart: prevSide, sideEnd: side.length })
  }
  return changes
}

/**
 * Maps a base line index to the corresponding index into `side`, using that
 * side's own changes. The base index must fall outside every change's
 * interior (at a boundary or in a stable stretch), which holds for every
 * index this module looks up.
 */
function mapBaseIndex(changes, baseIndex) {
  let offset = 0
  for (const change of changes) {
    if (change.baseEnd <= baseIndex) {
      offset += change.sideEnd - change.sideStart - (change.baseEnd - change.baseStart)
    } else {
      break
    }
  }
  return baseIndex + offset
}

/**
 * Groups the changes from both sides into regions ordered by where they
 * start in the base, absorbing any change that starts at or before the
 * region's current end and extending the end to cover it.
 */
function buildRegions(mineChanges, theirsChanges) {
  const tagged = [...mineChanges, ...theirsChanges].sort((a, b) => {
    if (a.baseStart !== b.baseStart) return a.baseStart - b.baseStart
    if (a.side === b.side) return 0
    return a.side === 'mine' ? -1 : 1
  })
  const regions = []
  let current = null
  for (const change of tagged) {
    if (current === null) {
      current = { start: change.baseStart, end: change.baseEnd, changes: [change] }
    } else if (change.baseStart <= current.end) {
      current.end = Math.max(current.end, change.baseEnd)
      current.changes.push(change)
    } else {
      regions.push(current)
      current = { start: change.baseStart, end: change.baseEnd, changes: [change] }
    }
  }
  if (current !== null) regions.push(current)
  return regions
}

