  const mineChanges = computeChanges(mine, base, 'mine')
  const theirsChanges = computeChanges(theirs, base, 'theirs')
  const regions = buildRegions(mineChanges, theirsChanges)

  const blocks = []
  let cursor = 0
  for (const region of regions) {
    if (region.start > cursor) {
      blocks.push({ kind: 'stable', lines: base.slice(cursor, region.start) })
    }
    const mineLines = mine.slice(mapBaseIndex(mineChanges, region.start), mapBaseIndex(mineChanges, region.end))
    const theirsLines = theirs.slice(mapBaseIndex(theirsChanges, region.start), mapBaseIndex(theirsChanges, region.end))
