    } else if (linesEqual(mineLines, baseLines)) {
      blocks.push({ kind: 'theirs', lines: theirsLines })
    } else if (linesEqual(theirsLines, baseLines)) {
      blocks.push({ kind: 'mine', lines: mineLines })
    } else {
      blocks.push({ kind: 'conflict', mine: mineLines, base: baseLines, theirs: theirsLines })
    }
    cursor = region.end
  }
  if (cursor < base.length) {
    blocks.push({ kind: 'stable', lines: base.slice(cursor) })
  }
  return blocks
