{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js merge`, `node src/cli.js merge2` and
 * `node src/cli.js regions` each read three documents from standard input and
 * report the three-way merge of the second into the first and the third.
 */

import { resolveMerge } from './diff3.js'

const MODES = new Set(['merge', 'merge2', 'regions'])

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function splitDocuments(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  const parts = [[]]
  for (const line of lines) {
    if (line === '%%%') parts.push([])
    else parts[parts.length - 1].push(line)
  }
  if (parts.length !== 3) fail('expected three parts separated by %%%')
  return parts
}

function renderMerge(blocks, includeBase) {
  const out = []
  let conflict = false
  for (const block of blocks) {
    if (block.kind === 'conflict') {
      conflict = true
      out.push('<<<<<<< mine', ...block.mine)
      if (includeBase) out.push('||||||| base', ...block.base)
      out.push('=======', ...block.theirs, '>>>>>>> theirs')
    } else {
      out.push(...block.lines)
    }
  }
  return { out, conflict }
}

function renderRegions(blocks) {
  const out = []
  let conflict = false
  for (const block of blocks) {
    if (block.kind === 'conflict') {
      conflict = true
      out.push(`conflict mine=${block.mine.length} base=${block.base.length} theirs=${block.theirs.length}`)
    } else {
      out.push(`${block.kind} ${block.lines.length}`)
    }
  }
  return { out, conflict }
}

function main() {
  const mode = process.argv[2]
  if (process.argv.length !== 3 || !MODES.has(mode)) {
    fail('usage: cli.js merge|merge2|regions')
  }

